import asyncio, os, signal, threading, warnings
from run import run_tasks
def make(i):
    async def task():
        try:
            await asyncio.sleep(5)
        finally:
            pass
    return task
def fire():
    import time; time.sleep(0.2); os.kill(os.getpid(), signal.SIGINT)
async def main():
    threading.Thread(target=fire, daemon=True).start()
    await run_tasks([make(i) for i in range(5)], max_concurrent=2)
try:
    asyncio.run(main())
except KeyboardInterrupt:
    print('OK: no RuntimeWarning, KeyboardInterrupt propagated')
